function applyPageTranslations(lang) {
    if (!TRANSLATIONS[lang]) lang = "en";
    const dict = TRANSLATIONS[lang];
    document.querySelectorAll("[data-i18n]").forEach(function (el) {
        const key = el.getAttribute("data-i18n");
        if (dict[key] === undefined) return;
        if (HTML_KEYS.indexOf(key) !== -1) {
            el.innerHTML = dict[key];
        } else {
            el.textContent = dict[key];
        }
    });
    document.documentElement.setAttribute("lang", lang);
    document.documentElement.setAttribute("dir", RTL_LANGS.indexOf(lang) !== -1 ? "rtl" : "ltr");
    document.querySelectorAll(".lang-switcher").forEach(function (sel) {
        sel.value = lang;
    });
    try { localStorage.setItem("vocosafe_lang", lang); } catch (e) {}
}

function changeLang(val) {
    applyPageTranslations(val);
}

document.addEventListener("DOMContentLoaded", function () {
    let saved = "en";
    try { saved = localStorage.getItem("vocosafe_lang") || "en"; } catch (e) {}
    if (!TRANSLATIONS[saved]) saved = "en";
    applyPageTranslations(saved);
});
